from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations, product


def _route(data, coupon_rule, minimum_duration, exact_coupons):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    coupons = data["coupons"]
    start = data["start"]
    initial = (source, initial_mask, 0)
    distances = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full and
                (not exact_coupons or used == coupons)):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                if "discount" in edge:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                else:
                    duration = edge["duration"]
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask,
                                           next_used))
    return {"arrival": None}


def _route_solver(rule, minimum, exact):
    return lambda data: _route(data, rule, minimum, exact)


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    return numerator // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, data["rounding"])
        tax = _round(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = {}
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, []) and
                          (name not in pins or row["version"] == pins[name]),
                          reverse=True)
        domains[name] = versions

    roots = data["roots"]
    choices = [([-1] + domains[name]) for name in names]
    for vector in product(*choices):
        selected = dict(zip(names, vector))
        if any(selected.get(name, -1) < bounds[0] or
               selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue

        rows = {name: next((row for row in packages[name]
                            if row["version"] == selected[name]), None)
                for name in names if selected[name] != -1}
        reachable = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            version = selected.get(name, -1)
            if version == -1 or name not in rows:
                valid = False
                break
            reachable.add(name)
            edges[name] = []
            for dep in rows[name].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target, -1)
                if target_version < dep["min"] or target_version > dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
                pending.append(target)
        if not valid or reachable != {name for name in names
                                      if selected[name] != -1}:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in reachable):
            continue
        return {"versions": {name: selected[name] for name in names
                             if selected[name] != -1}}
    return {"error": "unsatisfiable"}


def _intervals(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if data["k"] > len(jobs) or mandatory & blocked:
        return {"error": "impossible"}
    options = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in options}):
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(options, data["k"]):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": _route_solver("exact", 2, True),
    "component_02": _route_solver("at_most", 1, False),
    "component_03": _route_solver("exact", 1, True),
    "component_04": _route_solver("at_most", 2, False),
    "component_05": _route_solver("exact", 2, True),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _intervals,
}
